import { jsPDF } from 'jspdf';

export interface CertificateData {
  studentName: string;
  studentCode?: string;
  courseTitle: string;
  monthYear?: string;
  dateOfIssue?: string;
}

const CERTIFICATE_TEMPLATE_B64 = "data:image/png;base64,";

export const generateStudentCertificatePDF = (data: CertificateData) => {
  // A4 Landscape: 297mm width x 210mm height
  const doc = new jsPDF({
    orientation: 'landscape',
    unit: 'mm',
    format: 'a4',
  });

  const pageWidth = 297;
  const pageHeight = 210;

  // Clean strings without emojis
  const clean = (str?: string) => {
    if (!str) return '';
    return str
      .replace(/[\u{1F600}-\u{1F64F}\u{1F300}-\u{1F5FF}\u{1F680}-\u{1F6FF}\u{1F1E0}-\u{1F1FF}\u{2600}-\u{26FF}\u{2700}-\u{27BF}\u{1F900}-\u{1F9FF}\u{1F018}-\u{1F270}\u{238C}-\u{2454}\u{20D0}-\u{20FF}]/gu, '')
      .replace(/[★☆]/g, '')
      .trim();
  };

  const studentName = clean(data.studentName) || 'Student Name';
  const trackName = clean(data.courseTitle) || 'AI track';
  const monthYear = clean(data.monthYear) || 'July 2026';

  // 1. Draw High-Resolution Certificate Background Template
  try {
    doc.addImage(CERTIFICATE_TEMPLATE_B64, 'PNG', 0, 0, pageWidth, pageHeight);
  } catch (e) {
    console.error('Failed to draw certificate template:', e);
  }

  // 2. Draw Dynamic Student Name (Centered above the cyan line)
  doc.setTextColor(11, 37, 69); // #0B2545 Deep Dark Navy
  doc.setFont('helvetica', 'bold');

  // Dynamic font sizing for student name based on length
  let nameFontSize = 26;
  if (studentName.length > 32) {
    nameFontSize = 20;
  } else if (studentName.length > 25) {
    nameFontSize = 22;
  } else if (studentName.length > 18) {
    nameFontSize = 24;
  }

  doc.setFontSize(nameFontSize);
  // Y position around 98mm in landscape A4
  doc.text(studentName, pageWidth / 2, 98.5, { align: 'center' });

  // 3. Draw Certification Description (Centered below the cyan line)
  doc.setTextColor(30, 41, 59); // #1E293B Slate 800
  doc.setFont('times', 'normal'); // Serif / Georgia style
  doc.setFontSize(14.5);

  const descLine1 = 'For completing an internship program for the';
  const descLine2 = `month of (${monthYear}) at Innovera in ${trackName.toLowerCase().endsWith('track') ? trackName : `${trackName} track`}`;

  doc.text(descLine1, pageWidth / 2, 118, { align: 'center' });
  doc.text(descLine2, pageWidth / 2, 125.5, { align: 'center' });

  // Save the PDF
  const filename = `Certificate_${studentName.replace(/\s+/g, '_')}_${data.studentCode || 'INV'}.pdf`;
  doc.save(filename);
};

/**
 * Generate a high-resolution PNG image on canvas and download it
 */
export const generateStudentCertificatePNG = (data: CertificateData): Promise<string> => {
  return new Promise((resolve, reject) => {
    const canvas = document.createElement('canvas');
    canvas.width = 3000;
    canvas.height = 2118;
    const ctx = canvas.getContext('2d');
    if (!ctx) {
      reject(new Error('Canvas context not available'));
      return;
    }

    const img = new Image();
    img.crossOrigin = 'anonymous';
    img.onload = () => {
      // Draw background template
      ctx.drawImage(img, 0, 0, canvas.width, canvas.height);

      const clean = (str?: string) => {
        if (!str) return '';
        return str
          .replace(/[\u{1F600}-\u{1F64F}\u{1F300}-\u{1F5FF}\u{1F680}-\u{1F6FF}\u{1F1E0}-\u{1F1FF}\u{2600}-\u{26FF}\u{2700}-\u{27BF}\u{1F900}-\u{1F9FF}\u{1F018}-\u{1F270}\u{238C}-\u{2454}\u{20D0}-\u{20FF}]/gu, '')
          .replace(/[★☆]/g, '')
          .trim();
      };

      const studentName = clean(data.studentName) || 'Student Name';
      const trackName = clean(data.courseTitle) || 'AI track';
      const monthYear = clean(data.monthYear) || 'July 2026';

      // Draw Student Name
      ctx.fillStyle = '#0B2545';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';

      let nameFontSize = 105;
      if (studentName.length > 32) {
        nameFontSize = 80;
      } else if (studentName.length > 25) {
        nameFontSize = 90;
      }
      ctx.font = `bold ${nameFontSize}px "Segoe UI", Arial, sans-serif`;
      ctx.fillText(studentName, canvas.width / 2, canvas.height * 0.465);

      // Draw Description
      ctx.fillStyle = '#14233C';
      ctx.font = '62px Georgia, serif';
      const descLine1 = 'For completing an internship program for the';
      const descLine2 = `month of (${monthYear}) at Innovera in ${trackName.toLowerCase().endsWith('track') ? trackName : `${trackName} track`}`;

      ctx.fillText(descLine1, canvas.width / 2, canvas.height * 0.556);
      ctx.fillText(descLine2, canvas.width / 2, canvas.height * 0.592);

      // Convert to blob and download
      canvas.toBlob((blob) => {
        if (blob) {
          const url = URL.createObjectURL(blob);
          const a = document.createElement('a');
          a.href = url;
          a.download = `Certificate_${studentName.replace(/\s+/g, '_')}_${data.studentCode || 'INV'}.png`;
          document.body.appendChild(a);
          a.click();
          document.body.removeChild(a);
          URL.revokeObjectURL(url);
          resolve(url);
        } else {
          reject(new Error('Failed to create image blob'));
        }
      }, 'image/png');
    };

    img.onerror = (err) => reject(err);
    img.src = CERTIFICATE_TEMPLATE_B64;
  });
};
